import sys

def main():
    line = sys.stdin.read().strip()
    if not line:
        return
    parts = list(map(int, line.split()))
    if len(parts) != 2:
        return
    a, b = parts

    if abs(a - b) <= 1 and (a + b) % 2 == 1:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
